					for _, name := range installedNames {
						if _, ok := selectedSet[string(name)]; !ok {
							ag, err := agent.Get(name)
							if err != nil {
								continue
							}
							return fmt.Errorf("cannot remove %s — use `entire configure --remove %s` to remove it", ag.Type(), name)
						}
					}
					return nil
				}).
				Value(&selectedAgentNames),
		),
	)

