 53→	// AbsoluteGitHookPath embeds the full binary path in git hooks instead of
 54→	// bare "entire". This is needed for GUI git clients (Xcode, Tower, etc.)
 55→	// that don't source shell profiles and can't find "entire" on PATH.
 56→	AbsoluteGitHookPath bool `json:"absolute_git_hook_path,omitempty"`
 57→
 58→	// Telemetry controls anonymous usage analytics.
 59→	// nil = not asked yet (show prompt), true = opted in, false = opted out
 60→	Telemetry *bool `json:"telemetry,omitempty"`
 61→
 62→	// CommitLinking controls how commits are linked to agent sessions.
 63→	// "always" = auto-link without prompting, "prompt" = ask on each commit.
 64→	// Defaults to "prompt" (preserves existing user behavior).
 65→	CommitLinking string `json:"commit_linking,omitempty"`
 66→
 67→	// ExternalAgents enables discovery and registration of external agent
 68→	// plugins (entire-agent-* binaries on $PATH). Defaults to false.
 69→	ExternalAgents bool `json:"external_agents,omitempty"`
