 86→// Load loads the Entire settings from .entire/settings.json,
 87→// then applies any overrides from .entire/settings.local.json if it exists.
 88→// Returns default settings if neither file exists.
 89→// Works correctly from any subdirectory within the repository.
 90→func Load(ctx context.Context) (*EntireSettings, error) {
 91→	// Get absolute paths for settings files
 92→	settingsFileAbs, err := paths.AbsPath(ctx, EntireSettingsFile)
 93→	if err != nil {
 94→		settingsFileAbs = EntireSettingsFile // Fallback to relative
 95→	}
 96→	localSettingsFileAbs, err := paths.AbsPath(ctx, EntireSettingsLocalFile)
 97→	if err != nil {
 98→		localSettingsFileAbs = EntireSettingsLocalFile // Fallback to relative
 99→	}
100→
101→	// Load base settings
102→	settings, err := loadFromFile(settingsFileAbs)
103→	if err != nil {
104→		return nil, fmt.Errorf("reading settings file: %w", err)
105→	}
106→
107→	// Apply local overrides if they exist
108→	localData, err := os.ReadFile(localSettingsFileAbs) //nolint:gosec // path is from AbsPath or constant
109→	if err != nil {
110→		if !os.IsNotExist(err) {
111→			return nil, fmt.Errorf("reading local settings file: %w", err)
112→		}
113→		// Local file doesn't exist, continue without overrides
114→	} else {
115→		if err := mergeJSON(settings, localData); err != nil {
116→			return nil, fmt.Errorf("merging local settings: %w", err)
117→		}
118→	}
119→
120→	return settings, nil
121→}
