123→// LoadFromFile loads settings from a specific file path without merging local overrides.
124→// Returns default settings if the file doesn't exist.
125→// Use this when you need to display individual settings files separately.
126→func LoadFromFile(filePath string) (*EntireSettings, error) {
127→	return loadFromFile(filePath)
128→}
