130→// loadFromFile loads settings from a specific file path.
131→// Returns default settings if the file doesn't exist.
132→func loadFromFile(filePath string) (*EntireSettings, error) {
133→	settings := &EntireSettings{
134→		Enabled: true, // Default to enabled
135→	}
136→
137→	data, err := os.ReadFile(filePath) //nolint:gosec // path is from caller
138→	if err != nil {
139→		if os.IsNotExist(err) {
140→			return settings, nil
141→		}
142→		return nil, fmt.Errorf("%w", err)
143→	}
144→
145→	dec := json.NewDecoder(bytes.NewReader(data))
146→	dec.DisallowUnknownFields()
147→	if err := dec.Decode(settings); err != nil {
148→		return nil, fmt.Errorf("parsing settings file: %w", err)
149→	}
150→
151→	// Validate commit_linking if set
152→	if settings.CommitLinking != "" && settings.CommitLinking != CommitLinkingAlways && settings.CommitLinking != CommitLinkingPrompt {
153→		return nil, fmt.Errorf("invalid commit_linking value %q: must be %q or %q", settings.CommitLinking, CommitLinkingAlways, CommitLinkingPrompt)
154→	}
155→
156→	return settings, nil
157→}
158→
159→// mergeJSON merges JSON data into existing settings.
160→// Only non-zero values from the JSON override existing settings.
161→func mergeJSON(settings *EntireSettings, data []byte) error {
162→	// First, validate that there are no unknown keys using strict decoding
163→	dec := json.NewDecoder(bytes.NewReader(data))
164→	dec.DisallowUnknownFields()
165→	var temp EntireSettings
166→	if err := dec.Decode(&temp); err != nil {
167→		return fmt.Errorf("parsing JSON: %w", err)
168→	}
169→
170→	// Parse into a map to check which fields are present
171→	var raw map[string]json.RawMessage
172→	if err := json.Unmarshal(data, &raw); err != nil {
173→		return fmt.Errorf("parsing JSON: %w", err)
174→	}
175→
176→	// Override enabled if present
177→	if enabledRaw, ok := raw["enabled"]; ok {
178→		var e bool
179→		if err := json.Unmarshal(enabledRaw, &e); err != nil {
180→			return fmt.Errorf("parsing enabled field: %w", err)
181→		}
182→		settings.Enabled = e
183→	}
184→
185→	// Override local_dev if present
186→	if localDevRaw, ok := raw["local_dev"]; ok {
187→		var ld bool
188→		if err := json.Unmarshal(localDevRaw, &ld); err != nil {
189→			return fmt.Errorf("parsing local_dev field: %w", err)
190→		}
191→		settings.LocalDev = ld
192→	}
193→
194→	// Override absolute_git_hook_path if present
195→	if ahpRaw, ok := raw["absolute_git_hook_path"]; ok {
196→		var ahp bool
197→		if err := json.Unmarshal(ahpRaw, &ahp); err != nil {
198→			return fmt.Errorf("parsing absolute_git_hook_path field: %w", err)
199→		}
200→		settings.AbsoluteGitHookPath = ahp
201→	}
202→
203→	// Override log_level if present and non-empty
204→	if logLevelRaw, ok := raw["log_level"]; ok {
205→		var ll string
206→		if err := json.Unmarshal(logLevelRaw, &ll); err != nil {
207→			return fmt.Errorf("parsing log_level field: %w", err)
208→		}
209→		if ll != "" {
210→			settings.LogLevel = ll
211→		}
212→	}
213→
214→	// Merge strategy_options if present
215→	if optionsRaw, ok := raw["strategy_options"]; ok {
216→		var opts map[string]any
217→		if err := json.Unmarshal(optionsRaw, &opts); err != nil {
218→			return fmt.Errorf("parsing strategy_options field: %w", err)
219→		}
220→		if settings.StrategyOptions == nil {
221→			settings.StrategyOptions = opts
222→		} else {
223→			for k, v := range opts {
224→				settings.StrategyOptions[k] = v
225→			}
226→		}
227→	}
228→
229→	// Override telemetry if present
230→	if telemetryRaw, ok := raw["telemetry"]; ok {
231→		var t bool
232→		if err := json.Unmarshal(telemetryRaw, &t); err != nil {
233→			return fmt.Errorf("parsing telemetry field: %w", err)
234→		}
235→		settings.Telemetry = &t
236→	}
237→
238→	// Override commit_linking if present and non-empty
239→	if commitLinkingRaw, ok := raw["commit_linking"]; ok {
240→		var cl string
241→		if err := json.Unmarshal(commitLinkingRaw, &cl); err != nil {
242→			return fmt.Errorf("parsing commit_linking field: %w", err)
243→		}
244→		if cl != "" {
245→			switch cl {
246→			case CommitLinkingAlways, CommitLinkingPrompt:
247→				settings.CommitLinking = cl
248→			default:
249→				return fmt.Errorf("invalid commit_linking value %q: must be %q or %q", cl, CommitLinkingAlways, CommitLinkingPrompt)
250→			}
251→		}
252→	}
253→
254→	// Override external_agents if present
255→	if externalAgentsRaw, ok := raw["external_agents"]; ok {
256→		var ea bool
257→		if err := json.Unmarshal(externalAgentsRaw, &ea); err != nil {
258→			return fmt.Errorf("parsing external_agents field: %w", err)
259→		}
260→		settings.ExternalAgents = ea
261→	}
262→
263→	return nil
264→}
