333→// CheckpointRemoteConfig holds the structured checkpoint remote configuration.
334→// Stored in strategy_options.checkpoint_remote as {"provider": "github", "repo": "org/repo"}.
335→type CheckpointRemoteConfig struct {
336→	Provider string // e.g., "github"
337→	Repo     string // e.g., "org/checkpoints-repo"
338→}
339→
340→// Owner returns the owner portion of the repo field (before the slash).
341→// Returns empty string if the repo field doesn't contain a slash.
342→func (c *CheckpointRemoteConfig) Owner() string {
343→	parts := strings.SplitN(c.Repo, "/", 2)
344→	if len(parts) < 2 {
345→		return ""
346→	}
347→	return parts[0]
348→}
