350→// GetCheckpointRemote returns the configured checkpoint remote.
351→// Expects a structured object: {"provider": "github", "repo": "org/repo"}.
352→// Returns nil if not configured, wrong type, or missing required fields.
353→func (s *EntireSettings) GetCheckpointRemote() *CheckpointRemoteConfig {
354→	if s.StrategyOptions == nil {
355→		return nil
356→	}
357→	val, ok := s.StrategyOptions["checkpoint_remote"]
358→	if !ok {
359→		return nil
360→	}
361→	m, ok := val.(map[string]any)
362→	if !ok {
363→		return nil
364→	}
365→	provider, providerOK := m["provider"].(string)
366→	repo, repoOK := m["repo"].(string)
367→	if !providerOK || !repoOK || provider == "" || repo == "" {
368→		return nil
369→	}
370→	if !strings.Contains(repo, "/") {
371→		return nil
372→	}
373→	return &CheckpointRemoteConfig{Provider: provider, Repo: repo}
374→}
