 50→// applyStrategyOptions sets strategy_options on settings from CLI flags.
 51→func (opts *EnableOptions) applyStrategyOptions(settings *EntireSettings) {
 52→	if opts.SkipPushSessions {
 53→		if settings.StrategyOptions == nil {
 54→			settings.StrategyOptions = make(map[string]interface{})
 55→		}
 56→		settings.StrategyOptions["push_sessions"] = false
 57→	}
 58→	if opts.CheckpointRemote != "" {
 59→		provider, repo, err := parseCheckpointRemoteFlag(opts.CheckpointRemote)
 60→		if err != nil {
 61→			fmt.Fprintf(os.Stderr, "Warning: invalid --checkpoint-remote format: %v\n", err)
 62→		} else {
 63→			if settings.StrategyOptions == nil {
 64→				settings.StrategyOptions = make(map[string]interface{})
 65→			}
 66→			settings.StrategyOptions["checkpoint_remote"] = map[string]any{
 67→				"provider": provider,
 68→				"repo":     repo,
 69→			}
 70→		}
 71→	}
 72→}
 73→
 74→// parseCheckpointRemoteFlag parses a "provider:owner/repo" string into its components.
 75→// Supported providers: "github".
 76→func parseCheckpointRemoteFlag(value string) (provider, repo string, err error) {
 77→	parts := strings.SplitN(value, ":", 2)
 78→	if len(parts) != 2 || parts[0] == "" || parts[1] == "" {
 79→		return "", "", fmt.Errorf("expected format provider:owner/repo (e.g., github:org/checkpoints-repo), got %q", value)
 80→	}
 81→
 82→	provider = parts[0]
 83→	repo = parts[1]
 84→
 85→	switch provider {
 86→	case "github":
 87→		// valid
 88→	default:
 89→		return "", "", fmt.Errorf("unsupported provider %q (supported: github)", provider)
 90→	}
 91→
 92→	repoParts := strings.SplitN(repo, "/", 2)
 93→	if len(repoParts) != 2 || repoParts[0] == "" || repoParts[1] == "" {
 94→		return "", "", fmt.Errorf("repo must be in owner/name format, got %q", repo)
 95→	}
 96→
 97→	return provider, repo, nil
 98→}
