100→// runSetupFlow runs the first-time setup flow (agent selection + hooks + settings).
101→// Shared by root command (no args), `entire configure`, and `entire enable` on fresh repos.
102→func runSetupFlow(ctx context.Context, w io.Writer, opts EnableOptions) error {
103→	// If external agents already enabled (via flag or prior config), discover first so they appear in the list.
104→	externalPreSelected := opts.ExternalAgents != nil && *opts.ExternalAgents
105→	if externalPreSelected {
106→		external.DiscoverAndRegister(ctx)
107→	}
108→
109→	agents, externalSelected, err := detectOrSelectAgent(ctx, w, nil, externalPreSelected)
110→	if err != nil {
111→		return fmt.Errorf("agent selection failed: %w", err)
112→	}
113→
114→	// Set external agents preference based on selection.
115→	opts.ExternalAgents = &externalSelected
116→
117→	return runEnableInteractive(ctx, w, agents, opts)
118→}
