120→// splitExternalAgentSelection separates the external agents sentinel from real agent names.
121→func splitExternalAgentSelection(names []string) (realNames []string, externalSelected bool) {
122→	realNames = make([]string, 0, len(names))
123→	for _, name := range names {
124→		if name == externalAgentsSentinel {
125→			externalSelected = true
126→			continue
127→		}
128→		realNames = append(realNames, name)
129→	}
130→	return realNames, externalSelected
131→}
