133→// runAddAgents shows which agents are currently enabled and lets the user add more.
134→// Already-installed agents cannot be deselected.
135→func runAddAgents(ctx context.Context, w io.Writer, opts EnableOptions) error {
136→	// Discover external agent plugins.
137→	external.DiscoverAndRegister(ctx)
138→
139→	installedNames := GetAgentsWithHooksInstalled(ctx)
140→
141→	// Show currently installed agents
142→	if len(installedNames) > 0 {
143→		displayNames := make([]string, 0, len(installedNames))
144→		for _, name := range installedNames {
145→			if ag, err := agent.Get(name); err == nil {
146→				displayNames = append(displayNames, string(ag.Type()))
147→			}
148→		}
149→		fmt.Fprintf(w, "Enabled agents: %s\n\n", strings.Join(displayNames, ", "))
150→	}
151→
152→	// Build pre-selection set from installed agents
153→	installedSet := make(map[types.AgentName]struct{}, len(installedNames))
154→	for _, name := range installedNames {
155→		installedSet[name] = struct{}{}
156→	}
157→
158→	// Check if we can prompt interactively
159→	if !canPromptInteractively() {
160→		fmt.Fprintln(w, "Cannot show agent selection in non-interactive mode.")
161→		fmt.Fprintln(w, "Use: entire configure --agent <name>")
162→		return nil
163→	}
164→
165→	options, allInstalled := buildAgentOptions(installedSet)
166→	externalCurrentlyEnabled := settings.IsExternalAgentsEnabled(ctx)
167→	if allInstalled && externalCurrentlyEnabled {
168→		fmt.Fprintln(w, "All available agents are already enabled.")
169→		return nil
170→	}
171→
172→	selectedAgentNames, err := promptAddAgents(options, installedNames)
173→	if err != nil {
174→		return err
175→	}
176→
177→	realSelectedNames, externalSelected := splitExternalAgentSelection(selectedAgentNames)
178→
179→	// Update external agents setting if it changed.
180→	if externalSelected != externalCurrentlyEnabled {
181→		if err := updateExternalAgentsSetting(ctx, w, externalSelected); err != nil {
182→			return err
183→		}
184→	}
185→
186→	// Find newly selected agents (not previously installed)
187→	var newAgents []agent.Agent
188→	for _, name := range realSelectedNames {
189→		if _, wasInstalled := installedSet[types.AgentName(name)]; wasInstalled {
190→			continue
191→		}
192→		ag, err := agent.Get(types.AgentName(name))
193→		if err != nil {
194→			return fmt.Errorf("failed to get agent %s: %w", name, err)
195→		}
196→		newAgents = append(newAgents, ag)
197→	}
198→
199→	if len(newAgents) == 0 {
200→		fmt.Fprintln(w, "No new agents selected.")
201→		return nil
202→	}
203→
204→	// Install hooks for newly selected agents only
205→	for _, ag := range newAgents {
206→		if _, err := setupAgentHooks(ctx, ag, opts.LocalDev, opts.ForceHooks); err != nil {
207→			return fmt.Errorf("failed to setup %s hooks: %w", ag.Type(), err)
208→		}
209→	}
210→
211→	newTypes := make([]string, 0, len(newAgents))
212→	for _, ag := range newAgents {
213→		newTypes = append(newTypes, string(ag.Type()))
214→	}
215→	fmt.Fprintf(w, "✓ Added agents: %s\n", strings.Join(newTypes, ", "))
216→
217→	return nil
218→}
