 817→// detectOrSelectAgent tries to auto-detect agents, or prompts the user to select.
 818→// Returns the detected/selected agents and any error.
 819→//
 820→// On first run (no hooks installed):
 821→//   - Single detected agent: used automatically
 822→//   - Multiple/no detected agents: interactive multi-select prompt
 823→//
 824→// On re-run (hooks already installed):
 825→//   - Always shows the interactive multi-select
 826→//   - Pre-selects only agents that have hooks installed (respects prior deselection)
 827→//
 828→// selectFn overrides the interactive prompt for testing. When nil, the real form is used.
 829→// It receives available agent names and returns the selected names.
 830→// externalAgentsPreSelected controls whether the "External Agents" option is pre-selected.
 831→// Returns the selected agents, whether external agents was selected, and any error.
 832→func detectOrSelectAgent(ctx context.Context, w io.Writer, selectFn func(available []string) ([]string, error), externalAgentsPreSelected bool) ([]agent.Agent, bool, error) {
 833→	// Check for agents with hooks already installed (re-run detection)
 834→	installedAgentNames := GetAgentsWithHooksInstalled(ctx)
 835→	hasInstalledHooks := len(installedAgentNames) > 0
 836→
 837→	// Try auto-detection
 838→	detected := agent.DetectAll(ctx)
 839→
 840→	// First run: use existing auto-detect shortcuts
 841→	if !hasInstalledHooks {
 842→		switch {
 843→		case len(detected) == 1:
 844→			fmt.Fprintf(w, "Detected agent: %s\n\n", detected[0].Type())
 845→			return detected, externalAgentsPreSelected, nil
 846→
 847→		case len(detected) > 1:
 848→			agentTypes := make([]string, 0, len(detected))
 849→			for _, ag := range detected {
 850→				agentTypes = append(agentTypes, string(ag.Type()))
 851→			}
 852→			fmt.Fprintf(w, "Detected multiple agents: %s\n", strings.Join(agentTypes, ", "))
 853→			fmt.Fprintln(w)
 854→		}
 855→	}
 856→
 857→	// Check if we can prompt interactively
 858→	if !canPromptInteractively() {
 859→		if hasInstalledHooks {
 860→			// Re-run without TTY — keep currently installed agents
 861→			agents := make([]agent.Agent, 0, len(installedAgentNames))
 862→			for _, name := range installedAgentNames {
 863→				ag, err := agent.Get(name)
 864→				if err != nil {
 865→					continue
 866→				}
 867→				agents = append(agents, ag)
 868→			}
 869→			return agents, externalAgentsPreSelected, nil
 870→		}
 871→		if len(detected) > 0 {
 872→			return detected, externalAgentsPreSelected, nil
 873→		}
 874→		defaultAgent := agent.Default()
 875→		if defaultAgent == nil {
 876→			return nil, false, errors.New("no default agent available")
 877→		}
 878→		fmt.Fprintf(w, "Agent: %s (use --agent to change)\n\n", defaultAgent.Type())
 879→		return []agent.Agent{defaultAgent}, externalAgentsPreSelected, nil
 880→	}
 881→
 882→	// Build pre-selection set.
 883→	// On re-run: only pre-select agents with hooks installed (respect prior deselection).
 884→	// On first run: pre-select all detected agents.
 885→	preSelectedSet := make(map[types.AgentName]struct{})
 886→	if hasInstalledHooks {
 887→		for _, name := range installedAgentNames {
 888→			preSelectedSet[name] = struct{}{}
 889→		}
 890→	} else {
 891→		for _, ag := range detected {
 892→			preSelectedSet[ag.Name()] = struct{}{}
 893→		}
 894→	}
 895→
 896→	// Build options from registered agents
 897→	agentNames := agent.List()
 898→	options := make([]huh.Option[string], 0, len(agentNames))
 899→	for _, name := range agentNames {
 900→		ag, err := agent.Get(name)
 901→		if err != nil {
 902→			continue
 903→		}
 904→		// Only show agents that support hooks
 905→		if _, ok := agent.AsHookSupport(ag); !ok {
 906→			continue
 907→		}
 908→		// Skip test-only agents (e.g., Vogon canary)
 909→		if to, ok := ag.(agent.TestOnly); ok && to.IsTestOnly() {
 910→			continue
 911→		}
 912→		opt := huh.NewOption(string(ag.Type()), string(name))
 913→		if _, isPreSelected := preSelectedSet[name]; isPreSelected {
 914→			opt = opt.Selected(true)
 915→		}
 916→		options = append(options, opt)
 917→	}
 918→
 919→	// Add "External Agents" toggle option at the end.
 920→	externalOpt := huh.NewOption("External Agents", externalAgentsSentinel)
 921→	if externalAgentsPreSelected {
 922→		externalOpt = externalOpt.Selected(true)
 923→	}
 924→	options = append(options, externalOpt)
 925→
 926→	if len(options) == 0 {
 927→		return nil, false, errors.New("no agents with hook support available")
 928→	}
 929→
 930→	// Collect available agent names for the selector
 931→	availableNames := make([]string, 0, len(options))
 932→	for _, opt := range options {
 933→		availableNames = append(availableNames, opt.Value)
 934→	}
 935→
 936→	var selectedAgentNames []string
 937→	if selectFn != nil {
 938→		var err error
 939→		selectedAgentNames, err = selectFn(availableNames)
 940→		if err != nil {
 941→			return nil, false, err
 942→		}
 943→		if len(selectedAgentNames) == 0 {
 944→			return nil, false, errors.New("no agents selected")
 945→		}
 946→	} else {
 947→		form := NewAccessibleForm(
 948→			huh.NewGroup(
 949→				huh.NewMultiSelect[string]().
 950→					Title("Which agents are you using?").
 951→					Description("Use space to select, enter to confirm.").
 952→					Options(options...).
 953→					Validate(func(selected []string) error {
 954→						if len(selected) == 0 {
 955→							return errors.New("please select at least one agent")
 956→						}
 957→						return nil
 958→					}).
 959→					Value(&selectedAgentNames),
 960→			),
 961→		)
 962→		if err := form.Run(); err != nil {
 963→			return nil, false, fmt.Errorf("agent selection cancelled: %w", err)
 964→		}
 965→	}
 966→
 967→	// Separate the external agents sentinel from real agent selections.
 968→	externalSelected := false
 969→	realAgentNames := make([]string, 0, len(selectedAgentNames))
 970→	for _, name := range selectedAgentNames {
 971→		if name == externalAgentsSentinel {
 972→			externalSelected = true
 973→			continue
 974→		}
 975→		realAgentNames = append(realAgentNames, name)
 976→	}
 977→
 978→	selectedAgents := make([]agent.Agent, 0, len(realAgentNames))
 979→	for _, name := range realAgentNames {
 980→		selectedAgent, err := agent.Get(types.AgentName(name))
 981→		if err != nil {
 982→			return nil, false, fmt.Errorf("failed to get selected agent %s: %w", name, err)
 983→		}
 984→		selectedAgents = append(selectedAgents, selectedAgent)
 985→	}
 986→
 987→	agentTypes := make([]string, 0, len(selectedAgents))
 988→	for _, ag := range selectedAgents {
 989→		agentTypes = append(agentTypes, string(ag.Type()))
 990→	}
 991→	fmt.Fprintf(w, "\nSelected agents: %s\n\n", strings.Join(agentTypes, ", "))
 992→	return selectedAgents, externalSelected, nil
 993→}
