1039→// If strategyName is provided, it sets the strategy; otherwise uses default.
1040→func setupAgentHooksNonInteractive(ctx context.Context, w io.Writer, ag agent.Agent, opts EnableOptions) error {
1041→	agentName := ag.Name()
1042→	// Check if agent supports hooks
1043→	hookAgent, ok := agent.AsHookSupport(ag)
1044→	if !ok {
1045→		return fmt.Errorf("agent %s does not support hooks", agentName)
1046→	}
1047→
1048→	fmt.Fprintf(w, "Agent: %s\n\n", ag.Type())
1049→
1050→	// Install agent hooks (agent hooks don't depend on settings)
1051→	installedHooks, err := hookAgent.InstallHooks(ctx, opts.LocalDev, opts.ForceHooks)
1052→	if err != nil {
1053→		return fmt.Errorf("failed to install hooks for %s: %w", agentName, err)
1054→	}
1055→
1056→	// Setup .entire directory
1057→	if _, err := setupEntireDirectory(ctx); err != nil {
1058→		return fmt.Errorf("failed to setup .entire directory: %w", err)
1059→	}
1060→
1061→	// Load existing settings to preserve other options (like strategy_options.push)
1062→	settings, err := LoadEntireSettings(ctx)
1063→	if err != nil {
1064→		// If we can't load, start with defaults
1065→		settings = &EntireSettings{}
1066→	}
1067→	settings.Enabled = true
1068→	if opts.LocalDev {
1069→		settings.LocalDev = true
1070→	}
1071→	if opts.AbsoluteGitHookPath {
1072→		settings.AbsoluteGitHookPath = true
1073→	}
1074→	if opts.ExternalAgents != nil {
1075→		settings.ExternalAgents = *opts.ExternalAgents
1076→	}
1077→
1078→	opts.applyStrategyOptions(settings)
1079→
1080→	// Handle telemetry for non-interactive mode
1081→	// Note: if telemetry is nil (not configured), it defaults to disabled
1082→	if !opts.Telemetry || os.Getenv("ENTIRE_TELEMETRY_OPTOUT") != "" {
1083→		f := false
1084→		settings.Telemetry = &f
1085→	}
1086→
1087→	if err := SaveEntireSettings(ctx, settings); err != nil {
1088→		return fmt.Errorf("failed to save settings: %w", err)
1089→	}
1090→
1091→	// Use settings values (merged from existing config + flags) for hook installation
1092→	// This ensures re-running `entire enable --agent X` without flags preserves existing settings
1093→	if _, err := strategy.InstallGitHook(ctx, true, settings.LocalDev, settings.AbsoluteGitHookPath); err != nil {
1094→		return fmt.Errorf("failed to install git hooks: %w", err)
1095→	}
1096→	strategy.CheckAndWarnHookManagers(ctx, w, settings.LocalDev, settings.AbsoluteGitHookPath)
1097→
1098→	if installedHooks == 0 {
1099→		msg := fmt.Sprintf("Hooks for %s already installed", ag.Description())
1100→		if ag.IsPreview() {
1101→			msg += " (Preview)"
1102→		}
1103→		fmt.Fprintf(w, "%s\n", msg)
1104→	} else {
1105→		msg := fmt.Sprintf("Installed %d hooks for %s", installedHooks, ag.Description())
1106→		if ag.IsPreview() {
1107→			msg += " (Preview)"
1108→		}
1109→		fmt.Fprintf(w, "%s\n", msg)
1110→	}
1111→
1112→	fmt.Fprintf(w, "✓ Project configured (%s)\n", configDisplayProject)
1113→
1114→	if err := strategy.EnsureSetup(ctx); err != nil {
1115→		return fmt.Errorf("failed to setup strategy: %w", err)
1116→	}
1117→
1118→	fmt.Fprintln(w, "\nReady.")
1119→
1120→	if repo, err := strategy.OpenRepository(ctx); err == nil && strategy.IsEmptyRepository(repo) {
1121→		fmt.Fprintln(w)
1122→		fmt.Fprintln(w, "Note: Session checkpoints require at least one commit. To get started,")
1123→		fmt.Fprintln(w, "commit the configuration files (e.g. .entire/, .claude/).")
1124→	}
1125→
1126→	return nil
1127→}
