1137→// determineSettingsTarget decides whether to write to settings.local.json based on:
1138→// - Whether settings.json already exists
1139→// - The --local and --project flags
1140→// Returns (useLocal, showNotification).
1141→func determineSettingsTarget(entireDir string, useLocal, useProject bool) (bool, bool) {
