 50→// applyStrategyOptions sets strategy_options on settings from CLI flags.
 51→func (opts *EnableOptions) applyStrategyOptions(settings *EntireSettings) {
 52→	if opts.SkipPushSessions {
 53→		if settings.StrategyOptions == nil {
 54→			settings.StrategyOptions = make(map[string]interface{})
 55→		}
 56→		settings.StrategyOptions["push_sessions"] = false
 57→	}
 58→	if opts.CheckpointRemote != "" {
 59→		provider, repo, err := parseCheckpointRemoteFlag(opts.CheckpointRemote)
 60→		if err != nil {
 61→			fmt.Fprintf(os.Stderr, "Warning: invalid --checkpoint-remote format: %v\n", err)
 62→		} else {
 63→			if settings.StrategyOptions == nil {
 64→				settings.StrategyOptions = make(map[string]interface{})
 65→			}
 66→			settings.StrategyOptions["checkpoint_remote"] = map[string]any{
 67→				"provider": provider,
 68→				"repo":     repo,
 69→			}
 70→		}
 71→	}
 72→}
