220→// buildAgentOptions builds agent multi-select options with the external agents toggle.
221→// Returns options and whether all real agents are already installed.
222→func buildAgentOptions(installedSet map[types.AgentName]struct{}) ([]huh.Option[string], bool) {
223→	agentNames := agent.List()
224→	options := make([]huh.Option[string], 0, len(agentNames)+1)
225→	allInstalled := true
226→	for _, name := range agentNames {
227→		ag, err := agent.Get(name)
228→		if err != nil {
229→			continue
230→		}
231→		if _, ok := agent.AsHookSupport(ag); !ok {
232→			continue
233→		}
234→		if to, ok := ag.(agent.TestOnly); ok && to.IsTestOnly() {
235→			continue
236→		}
237→		opt := huh.NewOption(string(ag.Type()), string(name))
238→		if _, installed := installedSet[name]; installed {
239→			opt = opt.Selected(true)
240→		} else {
241→			allInstalled = false
242→		}
243→		options = append(options, opt)
244→	}
245→
246→	// Add "External Agents" toggle option at the end.
247→	externalOpt := huh.NewOption("External Agents", externalAgentsSentinel)
248→	if settings.IsExternalAgentsEnabled(context.Background()) {
249→		externalOpt = externalOpt.Selected(true)
250→	}
251→	options = append(options, externalOpt)
252→
253→	return options, allInstalled
254→}
