256→// promptAddAgents shows the multi-select form for adding agents.
257→func promptAddAgents(options []huh.Option[string], installedNames []types.AgentName) ([]string, error) {
258→	var selectedAgentNames []string
259→	form := NewAccessibleForm(
260→		huh.NewGroup(
261→			huh.NewMultiSelect[string]().
262→				Title("Enable more agents").
263→				Description("Use space to select, enter to confirm.").
264→				Options(options...).
265→				Validate(func(selected []string) error {
266→					if len(selected) == 0 {
267→						return errors.New("please select at least one agent")
268→					}
269→					// Ensure previously installed agents are still selected
270→					selectedSet := make(map[string]struct{}, len(selected))
271→					for _, s := range selected {
272→						selectedSet[s] = struct{}{}
273→					}
274→					for _, name := range installedNames {
275→						if _, ok := selectedSet[string(name)]; !ok {
276→							ag, err := agent.Get(name)
277→							if err != nil {
278→								continue
279→							}
280→							return fmt.Errorf("cannot remove %s — use `entire configure --remove %s` to remove it", ag.Type(), name)
281→						}
282→					}
283→					return nil
284→				}).
285→				Value(&selectedAgentNames),
286→		),
287→	)
288→	if err := form.Run(); err != nil {
289→		return nil, fmt.Errorf("agent selection cancelled: %w", err)
290→	}
291→	return selectedAgentNames, nil
292→}
