 533→// runEnableInteractive runs the interactive enable flow.
 534→// agents must be provided by the caller (via detectOrSelectAgent).
 535→func runEnableInteractive(ctx context.Context, w io.Writer, agents []agent.Agent, opts EnableOptions) error {
 536→	// Uninstall hooks for agents that were previously active but are no longer selected
 537→	if err := uninstallDeselectedAgentHooks(ctx, w, agents); err != nil {
 538→		return fmt.Errorf("failed to clean up deselected agents: %w", err)
 539→	}
 540→
 541→	// Setup agent hooks for all selected agents
 542→	for _, ag := range agents {
 543→		if _, err := setupAgentHooks(ctx, ag, opts.LocalDev, opts.ForceHooks); err != nil {
 544→			return fmt.Errorf("failed to setup %s hooks: %w", ag.Type(), err)
 545→		}
 546→	}
 547→
 548→	// Setup .entire directory
 549→	if _, err := setupEntireDirectory(ctx); err != nil {
 550→		return fmt.Errorf("failed to setup .entire directory: %w", err)
 551→	}
 552→
 553→	// Load existing settings to preserve other options (like strategy_options.push)
 554→	settings, err := LoadEntireSettings(ctx)
 555→	if err != nil {
 556→		// If we can't load, start with defaults
 557→		settings = &EntireSettings{}
 558→	}
 559→	// Update the specific fields
 560→	settings.Enabled = true
 561→	if opts.LocalDev {
 562→		settings.LocalDev = true
 563→	}
 564→	if opts.AbsoluteGitHookPath {
 565→		settings.AbsoluteGitHookPath = true
 566→	}
 567→	if opts.ExternalAgents != nil {
 568→		settings.ExternalAgents = *opts.ExternalAgents
 569→	}
 570→
 571→	opts.applyStrategyOptions(settings)
 572→
 573→	// Determine which settings file to write to
 574→	// First run always creates settings.json (no prompt)
 575→	entireDirAbs, err := paths.AbsPath(ctx, paths.EntireDir)
 576→	if err != nil {
 577→		entireDirAbs = paths.EntireDir // Fallback to relative
 578→	}
 579→	shouldUseLocal, showNotification := determineSettingsTarget(entireDirAbs, opts.UseLocalSettings, opts.UseProjectSettings)
 580→
 581→	if showNotification {
 582→		fmt.Fprintln(w, "Info: Project settings exist. Saving to settings.local.json instead.")
 583→		fmt.Fprintln(w, "  Use --project to update the project settings file.")
 584→	}
 585→
 586→	// Save settings to the appropriate file.
 587→	saveSettings := func() error {
 588→		if shouldUseLocal {
 589→			return SaveEntireSettingsLocal(ctx, settings)
 590→		}
 591→		return SaveEntireSettings(ctx, settings)
 592→	}
 593→	if err := saveSettings(); err != nil {
 594→		return fmt.Errorf("failed to save settings: %w", err)
 595→	}
 596→
 597→	// Use settings values (merged from existing config + flags) for hook installation
 598→	// This ensures re-running `entire enable` without flags preserves existing settings
 599→	if _, err := strategy.InstallGitHook(ctx, true, settings.LocalDev, settings.AbsoluteGitHookPath); err != nil {
 600→		return fmt.Errorf("failed to install git hooks: %w", err)
 601→	}
 602→	strategy.CheckAndWarnHookManagers(ctx, w, settings.LocalDev, settings.AbsoluteGitHookPath)
 603→	fmt.Fprintln(w, "✓ Hooks installed")
 604→
 605→	configDisplay := configDisplayProject
 606→	if shouldUseLocal {
 607→		configDisplay = configDisplayLocal
 608→	}
 609→	fmt.Fprintf(w, "✓ Project configured (%s)\n", configDisplay)
 610→
 611→	// Ask about telemetry consent (only if not already asked)
 612→	fmt.Fprintln(w)
 613→	if err := promptTelemetryConsent(settings, opts.Telemetry); err != nil {
 614→		return fmt.Errorf("telemetry consent: %w", err)
 615→	}
 616→	// Save again to persist telemetry choice
 617→	if err := saveSettings(); err != nil {
 618→		return fmt.Errorf("failed to save settings: %w", err)
 619→	}
 620→
 621→	if err := strategy.EnsureSetup(ctx); err != nil {
 622→		return fmt.Errorf("failed to setup strategy: %w", err)
 623→	}
 624→
 625→	fmt.Fprintln(w, "\nReady.")
 626→
 627→	// Note about empty repos at the end, after setup is complete
 628→	if repo, err := strategy.OpenRepository(ctx); err == nil && strategy.IsEmptyRepository(repo) {
 629→		fmt.Fprintln(w)
 630→		fmt.Fprintln(w, "Note: Session checkpoints require at least one commit. To get started,")
 631→		fmt.Fprintln(w, "commit the configuration files (e.g. .entire/, .claude/).")
 632→	}
 633→
 634→	return nil
 635→}
