 688→// saveEnabledState writes settings to the target file and also updates the
 689→// other settings file if it exists, preventing local/project from getting
 690→// out of sync on the enabled field.
 691→func saveEnabledState(ctx context.Context, s *EntireSettings, useProjectSettings bool) error {
 692→	if useProjectSettings {
 693→		if err := SaveEntireSettings(ctx, s); err != nil {
 694→			return fmt.Errorf("failed to save settings: %w", err)
 695→		}
 696→		// Also update local if it exists, so it doesn't override
 697→		if localExists(ctx) {
 698→			if err := SaveEntireSettingsLocal(ctx, s); err != nil {
 699→				return fmt.Errorf("failed to save local settings: %w", err)
 700→			}
 701→		}
 702→	} else {
 703→		if err := SaveEntireSettingsLocal(ctx, s); err != nil {
 704→			return fmt.Errorf("failed to save local settings: %w", err)
 705→		}
 706→	}
 707→	return nil
 708→}
