 720→// runRemoveAgent removes hooks for a specific agent.
 721→func runRemoveAgent(ctx context.Context, w io.Writer, name string) error {
 722→	ag, err := agent.Get(types.AgentName(name))
 723→	if err != nil {
 724→		printWrongAgentError(w, name)
 725→		return NewSilentError(errors.New("wrong agent name"))
 726→	}
 727→
 728→	hookAgent, ok := agent.AsHookSupport(ag)
 729→	if !ok {
 730→		return fmt.Errorf("agent %s does not support hooks", name)
 731→	}
 732→
 733→	if !hookAgent.AreHooksInstalled(ctx) {
 734→		fmt.Fprintf(w, "%s hooks are not installed.\n", ag.Type())
 735→		return nil
 736→	}
 737→
 738→	if err := hookAgent.UninstallHooks(ctx); err != nil {
 739→		return fmt.Errorf("failed to remove %s hooks: %w", ag.Type(), err)
 740→	}
 741→
 742→	fmt.Fprintf(w, "Removed %s hooks.\n", ag.Type())
 743→	return nil
 744→}
