 765→// uninstallDeselectedAgentHooks removes hooks for agents that were previously
 766→// installed but are not in the selected list. This handles the case where a user
 767→// re-runs `entire enable` and deselects an agent.
 768→func uninstallDeselectedAgentHooks(ctx context.Context, w io.Writer, selectedAgents []agent.Agent) error {
 769→	installedNames := GetAgentsWithHooksInstalled(ctx)
 770→	if len(installedNames) == 0 {
 771→		return nil
 772→	}
 773→
 774→	selectedSet := make(map[types.AgentName]struct{}, len(selectedAgents))
 775→	for _, ag := range selectedAgents {
 776→		selectedSet[ag.Name()] = struct{}{}
 777→	}
 778→
 779→	var errs []error
 780→	for _, name := range installedNames {
 781→		if _, selected := selectedSet[name]; selected {
 782→			continue
 783→		}
 784→		ag, err := agent.Get(name)
 785→		if err != nil {
 786→			continue
 787→		}
 788→		hookAgent, ok := agent.AsHookSupport(ag)
 789→		if !ok {
 790→			continue
 791→		}
 792→		if err := hookAgent.UninstallHooks(ctx); err != nil {
 793→			errs = append(errs, fmt.Errorf("failed to uninstall %s hooks: %w", ag.Type(), err))
 794→		} else {
 795→			fmt.Fprintf(w, "Removed %s hooks\n", ag.Type())
 796→		}
 797→	}
 798→	return errors.Join(errs...)
 799→}
