1237→var errUnsupportedShell = errors.New("unsupported shell")
1238→
1239→// shellCompletionTarget returns the rc file path and completion lines for the
1240→// user's current shell.
1241→func shellCompletionTarget() (shellName, rcFile, completionLine string, err error) {
1242→	home, err := os.UserHomeDir()
1243→	if err != nil {
1244→		return "", "", "", fmt.Errorf("cannot determine home directory: %w", err)
1245→	}
1246→
1247→	shell := os.Getenv("SHELL")
1248→	switch {
1249→	case strings.Contains(shell, "zsh"):
1250→		return "Zsh",
1251→			filepath.Join(home, ".zshrc"),
1252→			"autoload -Uz compinit && compinit && source <(entire completion zsh)",
1253→			nil
1254→	case strings.Contains(shell, "bash"):
1255→		bashRC := filepath.Join(home, ".bashrc")
1256→		if _, err := os.Stat(filepath.Join(home, ".bash_profile")); err == nil {
1257→			bashRC = filepath.Join(home, ".bash_profile")
1258→		}
1259→		return "Bash",
1260→			bashRC,
1261→			"source <(entire completion bash)",
1262→			nil
1263→	case strings.Contains(shell, "fish"):
1264→		return "Fish",
1265→			filepath.Join(home, ".config", "fish", "config.fish"),
1266→			"entire completion fish | source",
1267→			nil
1268→	default:
1269→		return "", "", "", errUnsupportedShell
1270→	}
1271→}
1272→
1273→// promptShellCompletion offers to add shell completion to the user's rc file.
1274→// Only prompts if completion is not already configured.
1275→func promptShellCompletion(w io.Writer) error {
1276→	shellName, rcFile, completionLine, err := shellCompletionTarget()
1277→	if err != nil {
1278→		if errors.Is(err, errUnsupportedShell) {
1279→			fmt.Fprintf(w, "Note: Shell completion not available for your shell. Supported: zsh, bash, fish.\n")
1280→			return nil
1281→		}
1282→		return fmt.Errorf("shell completion: %w", err)
1283→	}
1284→
1285→	if isCompletionConfigured(rcFile) {
